import { Schema } from '../../schema';

type 帖子对象 = z.output<typeof Schema>['轮回界域']['帖子'][string];
type 回帖对象 = 帖子对象['回帖'][string];
type 私聊消息对象 = z.output<typeof Schema>['轮回界域']['好友'][string]['私聊'][string];

const 消息选项 = { type: 'message', message_id: -1 } as const;

function 当前时间(): string {
  const d = new Date();
  const 补零 = (n: number) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${补零(d.getMonth() + 1)}-${补零(d.getDate())} ${补零(d.getHours())}:${补零(d.getMinutes())}`;
}

function 生成ID(): string {
  return `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 10)}`;
}

function 提取JSON(text: string): Record<string, string> {
  const 去围栏 = text
    .trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/, '');
  const 起 = 去围栏.indexOf('{');
  const 止 = 去围栏.lastIndexOf('}');
  if (起 === -1 || 止 === -1) {
    throw new Error('AI 没有返回 JSON 对象');
  }
  return JSON.parse(去围栏.slice(起, 止 + 1));
}

async function 生成新帖(): Promise<void> {
  const 指令 = [
    '你正在为「轮回界域」论坛模拟一位轮回者的发帖。「轮回界域」是所有轮回者（包括尚未通过轮回世界的新人）随时可访问的私密论坛，轮回者在这里交流情报、分享心得、求助或交易。',
    '请基于轮回世界的通用氛围（生死考验、主线支线任务、强化兑换、主世界保密、团战风险等）写一条自然、有信息量的新帖子。',
    '不要暴露你在生成内容，直接用该轮回者的论坛口吻输出。',
    '输出必须是一个合法的 JSON 对象，只含三个字段，不要输出任何其它文字：{"标题":"...","作者":"...","内容":"..."}',
    '作者是发帖者的界域名（简短昵称，不要用「<user>」或玩家名）；标题概括主题；内容为 100～300 字的论坛发言。',
  ].join('\n');

  const 结果 = await generateRaw({
    should_silence: true,
    ordered_prompts: [
      { role: 'system', content: 指令 },
      { role: 'user', content: '请生成一条新的轮回界域帖子。' },
    ],
  });

  const 数据 = typeof 结果 === 'string' ? 提取JSON(结果) : 提取JSON(结果.content);
  const 新帖: 帖子对象 = {
    标题: String(数据['标题'] ?? '无标题').trim(),
    作者: String(数据['作者'] ?? '匿名轮回者').trim(),
    时间: 当前时间(),
    内容: String(数据['内容'] ?? '').trim(),
    回帖: {},
  };

  const mvu = Mvu.getMvuData(消息选项);
  _.set(mvu, `stat_data.轮回界域.帖子.${生成ID()}`, 新帖);
  await Mvu.replaceMvuData(mvu, 消息选项);
}

async function 生成回帖(帖子ID: string): Promise<void> {
  const mvu = Mvu.getMvuData(消息选项);
  const 帖子 = _.get(mvu, `stat_data.轮回界域.帖子.${帖子ID}`) as 帖子对象 | undefined;
  if (!帖子) {
    toastr.warning('该帖子已不存在', '轮回界域');
    return;
  }

  const 已有回帖 = _(帖子.回帖)
    .values()
    .map(回帖 => `${回帖.作者}：${回帖.内容}`)
    .join('\n');

  const 指令 = [
    '你正在为「轮回界域」论坛模拟一位轮回者对某个帖子的回帖。「轮回界域」是所有轮回者随时可访问的私密论坛。',
    `帖子标题：${帖子.标题}`,
    `楼主内容：${帖子.内容}`,
    `已有回帖：${已有回帖 || '（暂无）'}`,
    '请以另一位轮回者的论坛口吻写一条针对性的回帖，可以是补充情报、表达看法、追问或建议。',
    '不要暴露你在生成内容，不要提到「<user>」。',
    '输出必须是一个合法的 JSON 对象，只含两个字段，不要输出任何其它文字：{"作者":"...","内容":"..."}',
    '作者是回帖者的界域名（简短昵称）；内容为 30～200 字的论坛回帖。',
  ].join('\n');

  const 结果 = await generateRaw({
    should_silence: true,
    ordered_prompts: [
      { role: 'system', content: 指令 },
      { role: 'user', content: '请生成一条回帖。' },
    ],
  });

  const 数据 = typeof 结果 === 'string' ? 提取JSON(结果) : 提取JSON(结果.content);
  const 新回帖: 回帖对象 = {
    作者: String(数据['作者'] ?? '匿名轮回者').trim(),
    内容: String(数据['内容'] ?? '').trim(),
    时间: 当前时间(),
  };

  const 更新后 = Mvu.getMvuData(消息选项);
  _.set(更新后, `stat_data.轮回界域.帖子.${帖子ID}.回帖.${生成ID()}`, 新回帖);
  await Mvu.replaceMvuData(更新后, 消息选项);
}

async function 生成私聊回复(好友名: string): Promise<void> {
  const mvu = Mvu.getMvuData(消息选项);
  const 好友 = _.get(mvu, ['stat_data', '轮回界域', '好友', 好友名]) as
    | { 添加时间: string; 私聊: Record<string, 私聊消息对象> }
    | undefined;
  if (!好友) {
    toastr.warning('该好友已不存在', '轮回界域');
    return;
  }

  const 最近消息 = _(好友.私聊)
    .values()
    .sortBy(m => m.时间)
    .takeRight(20)
    .map(m => `${m.作者}：${m.内容}`)
    .join('\n');

  const 指令 = [
    '你正在「轮回界域」论坛中模拟一位 NPC 轮回者回复好友的一对一私聊。「轮回界域」是所有轮回者随时可访问的私密论坛。',
    `你的界域名是「${好友名}」，你是一名经历过轮回世界生死考验的轮回者。`,
    `以下是你与好友最近的私聊记录：\n${最近消息 || '（暂无，这是你们的第一次对话）'}`,
    '请针对好友最后的发言，用你本人的口吻回复一条私聊；可以谈任务情报、强化心得、约着组队或闲聊，语气比公开论坛更随意亲近。',
    '不要暴露你在生成内容，不要提到「<user>」，不要替好友说话。',
    '输出必须是一个合法的 JSON 对象，只含一个字段，不要输出任何其它文字：{"内容":"..."}',
    '内容为 20～200 字的私聊消息。',
  ].join('\n');

  const 结果 = await generateRaw({
    should_silence: true,
    ordered_prompts: [
      { role: 'system', content: 指令 },
      { role: 'user', content: '请回复好友的私聊。' },
    ],
  });

  const 数据 = typeof 结果 === 'string' ? 提取JSON(结果) : 提取JSON(结果.content);
  const 新消息: 私聊消息对象 = {
    作者: 好友名,
    时间: 当前时间(),
    内容: String(数据['内容'] ?? '').trim(),
  };

  const 更新后 = Mvu.getMvuData(消息选项);
  _.set(更新后, ['stat_data', '轮回界域', '好友', 好友名, '私聊', 生成ID()], 新消息);
  await Mvu.replaceMvuData(更新后, 消息选项);
}

$(() => {
  eventOn('轮回界域:生成新帖', async () => {
    try {
      await 生成新帖();
    } catch (error) {
      toastr.error(error instanceof Error ? error.message : '生成帖子失败', '轮回界域');
    }
  });

  eventOn('轮回界域:生成回帖', async (帖子ID: string) => {
    try {
      await 生成回帖(帖子ID);
    } catch (error) {
      toastr.error(error instanceof Error ? error.message : '生成回帖失败', '轮回界域');
    }
  });

  eventOn('轮回界域:生成私聊', async (好友名: string) => {
    try {
      await 生成私聊回复(好友名);
    } catch (error) {
      toastr.error(error instanceof Error ? error.message : '生成私聊回复失败', '轮回界域');
    }
  });
});
